describe('Sticky Header Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display sticky header when scrolling down', () => {
    // Verify header is visible initially
    cy.get('[data-testid="sticky-header"]').should('be.visible');
    cy.get('[data-testid="sticky-header"]').should('have.css', 'position', 'sticky');

    // Scroll down to test stickiness
    cy.get('[data-testid="page-content"]').scrollTo('bottom');

    // Verify header is still visible after scrolling
    cy.get('[data-testid="sticky-header"]').should('be.visible');
    cy.get('[data-testid="sticky-header"]').should('have.css', 'position', 'sticky');

    // Verify header content is still intact
    cy.get('[data-testid="sticky-header"]').should('contain', 'Logo');
    cy.get('[data-testid="sticky-header"]').should('contain', 'Menu');
    cy.get('[data-testid="sticky-header"]').should('contain', 'Contact');
  });

  it('should hide header when scrolling up past threshold', () => {
    // Scroll down to test stickiness
    cy.get('[data-testid="page-content"]').scrollTo('bottom');

    // Verify header is visible after scrolling
    cy.get('[data-testid="sticky-header"]').should('be.visible');

    // Scroll up to test threshold
    cy.get('[data-testid="page-content"]').scrollTo('top');

    // Verify header is no longer visible
    cy.get('[data-testid="sticky-header"]').should('not.exist');

    // Verify header content is gone
    cy.get('[data-testid="sticky-header"]').should('not.be.visible');
    cy.get('[data-testid="sticky-header"]').should('not.contain', 'Logo');
    cy.get('[data-testid="sticky-header"]').should('not.contain', 'Menu');
    cy.get('[data-testid="sticky-header"]').should('not.contain', 'Contact');
  });
});
